        if (!title.empty()) {
            int number_levels = stoi(level.empty()? "1" : level.c_str()); // Default headin is h1
            string tag = "h" + to_string(number_levels);
            html += "<" + tag + ">" + title + "</" + tag + ">\n";
        }
        escapedMd = matches.suffix().str();
    }

    // Bold/Italic/Underline
    const regex patternStyle("(?:(?:__|\\*\*)[^\\s]+\\1\\\\|(?://)__([^:]*(?=:))?|[\\/*_])(?:\\S+(?=(?:" +
                                regex.escape("|*,.-@[]<>`"))(?:[^.*\\-_]|\\B))*)(?=\\1\\s*$))",
                                regex_option::extended | regex_option::optimize);

