    while (regex_search(escapedMd, matches, patternBlockquote)) {
        string quote_text = matches[2].str();

        // Strip multiple spaces and newlines within blockquotes
        quote_text = regex_replace(quote_text,
                                    regex(R"(^|\n)\s+" +
                                          regex::escape("\n+|\n\r?|\r\n?\s+") +
                                          R"+"?),
                                    "$1");

        // Prepend each line with necessary indentation based on amount of consecutive whitespaces found.
        size_t whitespace_count =
