                       return regex_match(str, regex("[ \t]+"));
                   });
        // Use tab characters to avoid issues with mixed spaces/tabs.
        quote_text = regex_replace(quote_text, regex(R"(\n+)"), "\n");
        quote_text = regex_replace(
            quote_text, regex(R"(^\s*)" + regex::escape("\S+")), "$$1" + string(whitespace_count, '\t'));

        html += "<blockquote>" + quote_text + "</blockquote>\n";
        escapedMd = matches.suffix().str();
    }

    // Unordered Lists
    const regex patternList(R"((?:^|\n) *([*+-]\s*)) (.+) (?=\n *[-+* ]|$))");
    while (regex_search(escapedMd, matches, patternList)) {
        string bullet_char = matches[1];
        string list_item = matches[2];

        // Strip leading/trailing whitespace/newlines within list items
        list_item = regex_replace(list_item, regex(R"(^|\n)\s+(\S+)"), "$1$2");
