Here's an example of how you can achieve this task in C++. First, let's create a function to count the number of occurrences:

```cpp
#include <iostream>
#include <fstream>

// Function to count occurrences of a specific word
int countOccurrences(const std::string& wordToCount, const std::vector<std::string>& words) {
    int occurrence = 0;
    for (const auto& word : words) {
        if (word == wordToCount) {
            ++occurrence;
        }
    }
    return occurrence;
}
```

This `countOccurrences` function takes two arguments: The first argument is the word we want to search for (`wordToCount`). The second argument represents a vector of strings containing each line split into individual words.

Now let's write a complete program for reading a text file line-by-line, splitting lines into words, counting occurrences of a specific word, and outputting the result:

```cpp
#include <iostream>
#include <fstream>
#include <sstream>
#include <algorithm> // For sort() function used later

using namespace std;

// Function to count occurrences of a specific word
int countOccurrences(const string& wordToCount, const vector<string>& words) {
    int occurrence = 0;
    for (auto& word : words) {
        if (word == wordToCount) {
            ++occurrence;
        }
    }
    return occurrence;
}

int main() {
    string filename;   // Name of input file
    cout << "Enter name of file: ";
    cin >> filename;

    ifstream inputFile(filename);
    if (!inputFile.is_open()) {
        cerr << "Error: Unable to open file!" << endl;
        return 1;
    }

    string line;
    vector<string> words;

    while (getline(inputFile, line)) {  // Read each line from file
        stringstream ss(line);          // Convert input string to stringstream
        string word;

        while (ss >> word) {             // Split current line into words and add them to vector
            if (::isspace(word[0])) {   // Remove leading white-spaces if present
                --word.size();           // Decrease size as we removed the white-space at beginning of string.
            }
            words.push_back(word);
        }

        sort(words.begin(), words.end()); // Sorting the words alphabetically 
        // We do so to avoid duplicates when checking the occurrence of the given word

        // Finding the specified word in the sorted list
        const string& queryWord = "given_word"; // Replace with your desired word to be searched
        int totalCount = countOccurrences(queryWord, words); 

        printf("Occurrences of '%s' in line %d: %d\n", queryWord.c_str(), words.size(), totalCount);

        // Clearing the vector before moving on to next iteration to ensure clean storage of results for next iteration
        words.clear();
    }

    inputFile.close();

    return 0;
}
```

In order to use this program, save it in a `.cpp` file and compile it using a compiler such as GCC or Clang. Then run your compiled executable with the name of the input file you want to process as command line argument, like this:

```
./a.out input.txt
```

When running the program above, make sure to replace `"given_word"` with the actual word you want to search for. This program considers partial matches too i.e., matches for substrings within other words will also contribute towards the total count. If you want to exclude partial matches, simply remove the call to `sort()` after split of the line, or modify the matching condition inside `countOccurrences()` accordingly.
